  it("shows the team result line and no score when the Team's scores are not shared or too few", () => {
    Scene.scene(
      { update, view },
      Scene.given(
        loaded(
          [
            soloRound(roundB, "Monthly pulse", "notShared"),
            soloRound(roundC, "Quarterly pulse", "belowMinimumGroupSize"),
          ],
          {},
