// THROWAWAY audit harness (#138). Not shipped, not committed.
// Renders the real App view/update with a fixture Model chosen by ?scene=<name>&lang=en|de.
import { Runtime } from "foldkit";
import { Option } from "effect";
import { fromString } from "foldkit/url";
import { initialModel, Message, Model, update, view } from "../src/app/App.ts";
import "../src/app/app.css";

const params = new URLSearchParams(location.search);
const sceneName = params.get("scene") ?? "teams";
const lang = (params.get("lang") ?? "en") as "en" | "de";
const de = lang === "de";
const t = (en: string, deText: string) => (de ? deText : en);

const url = (path: string) => Option.getOrThrow(fromString(`https://dashboard.surveybeat.app${path}`));
const base = (path: string): any => ({ ...initialModel(url(path)), browserLocale: lang });

const session = (admin = true): any => ({
  _tag: "SignedIn",
  organization: { id: "org-1", name: "Northwind Logistics" },
  organizationAdmin: admin,
  locale: lang,
  detectedLocale: null,
  organizationLocale: "en",
});

const T = "team-1";
const P = "pulse-1";
const day = (iso: string) => Date.parse(`${iso}T09:00:00Z`);

const teams = [
  { id: T, name: t("Platform Engineering", "Plattform-Entwicklung"), timeZone: "Europe/Berlin", yourRole: "lead" },
  { id: "team-2", name: t("Customer Success", "Kundenerfolg"), timeZone: "Europe/Berlin", yourRole: "member" },
  { id: "team-3", name: t("Warehouse Operations Hamburg", "Lagerbetrieb Hamburg"), timeZone: "Europe/Berlin", yourRole: null },
];

const roster = [
  { personId: "p-1", email: "grace.hopper@northwind.example", role: "lead", since: day("2026-09-01") },
  { personId: "p-2", email: "ada.lovelace@northwind.example", role: "member", since: day("2026-09-01") },
  { personId: "p-3", email: "alan.turing@northwind.example", role: "member", since: day("2026-09-03") },
  { personId: "p-4", email: "katherine.johnson@northwind.example", role: "member", since: day("2026-09-10") },
  { personId: "p-5", email: "margaret.hamilton@northwind.example", role: "member", since: day("2026-10-01") },
  { personId: "p-6", email: "edsger.dijkstra@northwind.example", role: "member", since: day("2026-10-14") },
];

const teamDetail = (yourRole: "lead" | "member" | null, opts: { viewResults?: boolean; emptyRoster?: boolean } = {}): any => ({
  team: { ...teams[0], yourRole },
  roster: opts.emptyRoster === true ? [] : roster,
  may: {
    update: yourRole === "lead",
    manageLeads: yourRole === "lead",
    manageMembers: yourRole === "lead",
    managePulses: yourRole === "lead",
    viewResults: opts.viewResults ?? yourRole !== null,
  },
});

const overviewDates = ["2026-09-21", "2026-09-28", "2026-10-05", "2026-10-12", "2026-10-19", "2026-10-26", "2026-11-02", "2026-11-09"];
const series = (vals: Array<number | null>) => vals.map((score, i) => ({ roundId: `r-${i}`, score }));
const overview: any = {
  teamId: T,
  rounds: overviewDates.map((d, i) => ({ roundId: `r-${i}`, plannedOpenDate: d })),
  dimensions: [
    { dimension: "workload", points: series([3.1, 3.0, 2.8, null, 2.6, 3.2, 3.4, 3.6]) },
    { dimension: "psychologicalSafety", points: series([4.0, 4.1, 3.9, 4.0, 4.2, 4.1, 4.3, 4.2]) },
    { dimension: "clarity", points: series([3.0, 3.2, 3.1, 3.5, 3.4, 3.8, 3.7, 4.0]) },
    { dimension: "recognition", points: series([3.6, 3.5, 3.6, 3.4, 3.7, 3.8, 3.6, 3.9]) },
  ],
  markers: [
    { actionId: "a-1", title: t("Protect focus time on Wednesdays", "Fokuszeit am Mittwoch schützen"), kind: "committed", at: day("2026-10-14") },
    { actionId: "a-1", title: t("Protect focus time on Wednesdays", "Fokuszeit am Mittwoch schützen"), kind: "done", at: day("2026-10-28") },
    { actionId: "a-2", title: t("Share the quarterly roadmap in the all-hands", "Quartals-Roadmap im All-Hands teilen"), kind: "committed", at: day("2026-11-04") },
  ],
};

const settings = (aiProcessing: boolean): any => ({
  name: "Northwind Logistics",
  minimumGroupSize: 4,
  aiProcessing,
  defaultLocale: "de",
  people: [
    { personId: "p-1", email: "grace.hopper@northwind.example", organizationAdmin: true, linked: true },
    { personId: "p-2", email: "ada.lovelace@northwind.example", organizationAdmin: false, linked: true },
    { personId: "p-3", email: "alan.turing@northwind.example", organizationAdmin: false, linked: false },
    { personId: "p-4", email: "katherine.johnson@northwind.example", organizationAdmin: false, linked: true },
  ],
});

const pulseSummary = (id: string, name: string, dayName: string, q: number): any => ({
  id,
  name,
  cadence: { _tag: "Weekly", day: dayName, time: "09:00" },
  questionCount: q,
  estimatedSeconds: q * 15,
});

const rating = (low: string, high: string, comment = true) => ({ _tag: "Rating", lowLabel: low, highLabel: high, comment });

const pulseDetail: any = {
  id: P,
  team: teams[0],
  settings: {
    name: t("Weekly check-in", "Wöchentlicher Check-in"),
    cadence: { _tag: "Weekly", day: "monday", time: "09:00" },
    answerWindowDays: 3,
    reviewWindowDays: 2,
    reminders: 1,
    anonymityMode: "anonymous",
    distribution: "invitation",
  },
  questions: [
    { questionId: "q-1", versionId: "v-1", templateKey: "workload", text: t("How manageable was your workload this week?", "Wie gut war deine Arbeitslast diese Woche zu bewältigen?"), type: rating(t("Overwhelming", "Überwältigend"), t("Very manageable", "Gut zu bewältigen")), dimension: "workload", hasAnswers: true, estimatedSeconds: 15 },
    { questionId: "q-2", versionId: "v-2", templateKey: "clarity", text: t("I know what is expected of me this week.", "Ich weiß, was diese Woche von mir erwartet wird."), type: rating(t("Disagree", "Stimme nicht zu"), t("Agree", "Stimme zu")), dimension: "clarity", hasAnswers: true, estimatedSeconds: 15 },
    { questionId: "q-3", versionId: "v-3", templateKey: null, text: t("Which meeting would you drop first?", "Welches Meeting würdest du zuerst streichen?"), type: { _tag: "SingleChoice", options: ["Standup", "Planning", "Retro", t("None", "Keines")] }, dimension: null, hasAnswers: false, estimatedSeconds: 10 },
    { questionId: "q-4", versionId: "v-4", templateKey: null, text: t("Anything else your Lead should know?", "Gibt es noch etwas, das deine Lead wissen sollte?"), type: { _tag: "LongText" }, dimension: null, hasAnswers: false, estimatedSeconds: 30 },
  ],
  estimatedSeconds: 70,
  warnings: [],
  templateQuestions: [
    { key: "psychologicalSafety", text: t("I can raise a concern without worrying about how it lands.", "Ich kann Bedenken äußern, ohne mir Sorgen zu machen, wie sie ankommen."), dimension: "psychologicalSafety", type: rating(t("Disagree", "Stimme nicht zu"), t("Agree", "Stimme zu")), estimatedSeconds: 15 },
    { key: "recognition", text: t("My work was noticed this week.", "Meine Arbeit wurde diese Woche wahrgenommen."), dimension: "recognition", type: rating(t("Disagree", "Stimme nicht zu"), t("Agree", "Stimme zu")), estimatedSeconds: 15 },
  ],
};

const roundSummary = (id: string, status: string, plannedOpenDate: string): any => ({
  id,
  pulseId: P,
  teamId: T,
  status,
  plannedOpenDate,
  plannedOpenAt: day(plannedOpenDate),
  openedAt: status === "scheduled" ? null : day(plannedOpenDate),
  plannedCloseAt: day(plannedOpenDate) + 3 * 86400000,
  closedAt: ["scheduled", "open"].includes(status) ? null : day(plannedOpenDate) + 3 * 86400000,
  pulseName: pulseDetail.settings.name,
});

const roundsList: any = {
  pulseId: P,
  rounds: [
    roundSummary("round-s", "scheduled", "2026-11-16"),
    roundSummary("round-o", "open", "2026-11-09"),
    roundSummary("round-r", "ready", "2026-11-02"),
    roundSummary("round-c", "closed", "2026-10-26"),
    roundSummary("round-sh", "shared", "2026-10-19"),
    roundSummary("round-x", "cancelled", "2026-10-12"),
  ],
};
const openDetail: any = {
  ...roundSummary("round-o", "open", "2026-11-09"),
  team: teams[0],
  effectiveMinimumGroupSize: 4,
  answerWindowDays: 3,
  reminders: 1,
  anonymityMode: "anonymous",
  distribution: "invitation",
  questions: [],
  failedInvitations: [
    { personId: "p-6", email: "edsger.dijkstra@northwind.example", reason: t("Mailbox full", "Postfach voll"), resendCount: 0 },
  ],
  createdAt: day("2026-11-01"),
};
delete openDetail.teamId;

const trend = (scores: number[]) =>
  scores.map((score, i) => ({ roundId: `r-${i}`, plannedOpenDate: overviewDates[overviewDates.length - scores.length + i], score, contributors: 6, hasGap: false }));
const dtrend = (scores: number[]) =>
  scores.map((score, i) => ({ roundId: `r-${i}`, plannedOpenDate: overviewDates[overviewDates.length - scores.length + i], score, usableQuestionCount: 1, hasGap: false }));
const typical = { status: "ready", completedUsableRounds: 6, totalRequiredUsableRounds: 6, typicalChange: 0.3 };

const questionResults: any[] = [
  {
    questionVersionId: "v-1", position: 1, text: pulseDetail.questions[0].text, type: pulseDetail.questions[0].type, dimension: "workload",
    contributors: 6, meetsMinimumGroupSize: true, score: 3.6,
    distribution: [{ option: 2, count: 1 }, { option: 3, count: 1 }, { option: 4, count: 3 }, { option: 5, count: 1 }],
    change: { change: 0.2, previousRoundDate: "2026-11-02", previousRoundId: "r-6", highlight: { isLargerThanUsual: false, direction: "rise", label: "", explanation: "" } },
    typicalChange: typical, trend: trend([2.6, 3.2, 3.4, 3.6]),
  },
  {
    questionVersionId: "v-2", position: 2, text: pulseDetail.questions[1].text, type: pulseDetail.questions[1].type, dimension: "clarity",
    contributors: 6, meetsMinimumGroupSize: true, score: 4.0,
    distribution: [{ option: 3, count: 1 }, { option: 4, count: 4 }, { option: 5, count: 1 }],
    change: { change: 0.5, previousRoundDate: "2026-11-02", previousRoundId: "r-6", highlight: { isLargerThanUsual: true, direction: "rise", label: t("Bigger change than usual", "Größere Veränderung als üblich"), explanation: "" } },
    typicalChange: typical, trend: trend([3.4, 3.8, 3.7, 4.0]),
  },
  {
    questionVersionId: "v-3", position: 3, text: pulseDetail.questions[2].text, type: pulseDetail.questions[2].type, dimension: null,
    contributors: 6, meetsMinimumGroupSize: true, score: null,
    distribution: [{ option: "Standup", count: 1 }, { option: "Planning", count: 3 }, { option: "Retro", count: 0 }, { option: t("None", "Keines"), count: 2 }],
    change: null, typicalChange: null, trend: [],
  },
  {
    questionVersionId: "v-4", position: 4, text: pulseDetail.questions[3].text, type: pulseDetail.questions[3].type, dimension: null,
    contributors: 4, meetsMinimumGroupSize: true, score: null, distribution: null, change: null, typicalChange: null, trend: [],
  },
];
const dimensionResults: any[] = [
  { dimension: "workload", score: 3.6, usableQuestionCount: 1, totalQuestionCount: 1, contributors: 6, meetsMinimumGroupSize: true,
    change: { change: 0.2, previousRoundDate: "2026-11-02", previousRoundId: "r-6", matchedQuestionCount: 1, currentQuestionCount: 1, annotation: null, highlight: null },
    typicalChange: typical, trend: dtrend([2.6, 3.2, 3.4, 3.6]) },
  { dimension: "clarity", score: 4.0, usableQuestionCount: 1, totalQuestionCount: 1, contributors: 6, meetsMinimumGroupSize: true,
    change: { change: 0.5, previousRoundDate: "2026-11-02", previousRoundId: "r-6", matchedQuestionCount: 1, currentQuestionCount: 1, annotation: null,
      highlight: { isLargerThanUsual: true, direction: "rise", label: t("Bigger change than usual", "Größere Veränderung als üblich"), explanation: t("Rose by 0.5; usually moves by 0.3", "Um 0,5 gestiegen; üblich sind 0,3") } },
    typicalChange: typical, trend: dtrend([3.4, 3.8, 3.7, 4.0]) },
];
const comments: any[] = [
  { questionVersionId: "v-1", text: t("Release week was intense, but the on-call swap helped a lot.", "Die Release-Woche war intensiv, aber der Bereitschaftstausch hat sehr geholfen.") },
  { questionVersionId: "v-1", text: t("Still too many interruptions from [redacted] requests.", "Immer noch zu viele Unterbrechungen durch [entfernt]-Anfragen.") },
  { questionVersionId: "v-4", text: t("Thanks for moving the planning meeting to the afternoon.", "Danke, dass das Planning auf den Nachmittag verlegt wurde.") },
  { questionVersionId: "v-4", text: t("Would love clearer priorities for the migration project.", "Ich wünsche mir klarere Prioritäten für das Migrationsprojekt.") },
];
const themes = (lead: boolean): any[] => [
  { label: t("Interruptions", "Unterbrechungen"), sentence: t("Several people say ad-hoc requests break up focused work.", "Mehrere Personen sagen, dass Ad-hoc-Anfragen konzentriertes Arbeiten unterbrechen."), ...(lead ? { supportingComments: 3 } : {}) },
  { label: t("Priorities", "Prioritäten"), sentence: t("People would like clearer priorities for the migration.", "Man wünscht sich klarere Prioritäten für die Migration."), ...(lead ? { supportingComments: 2 } : {}) },
];
const guide: any = {
  whatStoodOut: [t("Clarity rose more than usual, to 4.0.", "Klarheit ist stärker als üblich gestiegen, auf 4,0.")],
  whatPeopleRaised: [t("Interruptions from ad-hoc requests.", "Unterbrechungen durch Ad-hoc-Anfragen.")],
  actionsToCheckOn: [t("Protect focus time on Wednesdays (done).", "Fokuszeit am Mittwoch schützen (erledigt).")],
  questions: [t("Which requests could wait until Thursday?", "Welche Anfragen könnten bis Donnerstag warten?"), t("What would make the migration priorities clearer?", "Was würde die Prioritäten der Migration klarer machen?")],
};

const RID = "round-1";
const result = (o: any = {}): any => ({
  roundId: RID, pulseId: P, teamId: T, status: "shared", plannedOpenDate: "2026-11-09", anonymityMode: "anonymous",
  closedAt: day("2026-11-12"), effectiveMinimumGroupSize: 4, meetsMinimumGroupSize: true, eligibleMembersCount: 8,
  submissionsCount: 6, responseRate: 0.75, delayed: false, questions: questionResults, dimensions: dimensionResults, comments,
  ...o,
});
const actions: any[] = [
  { id: "a-1", teamId: T, roundId: RID, title: t("Protect focus time on Wednesdays", "Fokuszeit am Mittwoch schützen"), ownerId: "p-1", ownerEmail: "grace.hopper@northwind.example", dueDate: "2026-11-20", dimension: "workload", status: "committed", createdAt: day("2026-11-12"), updatedAt: day("2026-11-12"), doneAt: null },
  { id: "a-2", teamId: T, roundId: RID, title: t("Share the quarterly roadmap in the all-hands", "Quartals-Roadmap im All-Hands teilen"), ownerId: null, ownerEmail: null, dueDate: null, dimension: "clarity", status: "done", createdAt: day("2026-11-05"), updatedAt: day("2026-11-10"), doneAt: day("2026-11-10") },
];
const resultsUrl = `/teams/${T}/rounds/${RID}`;
const results = (role: "lead" | "member", r: any, o: any = {}): any => ({
  ...base(resultsUrl),
  session: session(role === "lead"),
  results: { _tag: "Loaded", result: r },
  teamDetail: { _tag: "Loaded", detail: teamDetail(role) },
  actions: { _tag: "Loaded", actions: o.actions ?? actions },
  roundNote: { _tag: "Loaded", note: o.note === undefined ? { roundId: RID, text: t("Thanks everyone. We'll try a quiet Wednesday morning for the next two weeks and check in again at the retro.", "Danke euch allen. Wir probieren die nächsten zwei Wochen einen ruhigen Mittwochvormittag aus und sprechen in der Retro wieder darüber."), updatedAt: day("2026-11-13") } : o.note },
});

const historyRound = (roundId: string, pulseName: string, date: string, teamResult: string): any => ({
  roundId, teamId: T, teamName: teams[0].name, pulseName, plannedOpenDate: date, teamResult,
  questions: [
    { questionVersionId: "v-1", position: 1, text: pulseDetail.questions[0].text, type: pulseDetail.questions[0].type, teamScore: teamResult === "shown" ? 3.6 : null },
    { questionVersionId: "v-3", position: 2, text: pulseDetail.questions[2].text, type: pulseDetail.questions[2].type, teamScore: null },
    { questionVersionId: "v-4", position: 3, text: pulseDetail.questions[3].text, type: pulseDetail.questions[3].type, teamScore: null },
  ],
});
const historyRounds = [
  historyRound("round-a", pulseDetail.settings.name, "2026-11-09", "shown"),
  historyRound("round-b", pulseDetail.settings.name, "2026-11-02", "notShared"),
  historyRound("round-c", t("Monthly team pulse", "Monatlicher Team-Puls"), "2026-10-05", "belowMinimumGroupSize"),
];
const kept: any = {
  "round-a": { "v-1": { value: 4, comment: t("Release week was intense.", "Die Release-Woche war intensiv.") }, "v-3": { value: 1 }, "v-4": { comment: t("Thanks for the quieter planning.", "Danke für das ruhigere Planning.") } },
};

